function __S(x){return String(x);}
var DEFURL='https://bachashuku.org';
var UA_STR='Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Mobile Safari/537.36';
function S(x){return String(x);}
function getsurl(){
  var u='';
  try{u=String((source.getLoginInfoMap()||{})['网址']||'');}catch(e){}
  if(!u||u=='null'||u=='undefined'||u.indexOf('http')!=0)u=DEFURL;
  while(u.length>0&&u.charAt(u.length-1)=='/')u=u.substring(0,u.length-1);
  return u;
}
function ckMerge(a,b){
  var m={},all=String(a||'')+';'+String(b||''),p=all.split(';');
  for(var i=0;i<p.length;i++){
    var s=p[i].trim();if(!s)continue;
    var e=s.indexOf('=');if(e<0)continue;
    var n=s.substring(0,e).trim(),v=s.substring(e+1).trim();
    if(n)m[n]=v;
  }
  var o=[];for(var k in m)o.push(k+'='+m[k]);
  return o.join('; ');
}
function hdBase(){
  var h={};
  h['User-Agent']=UA_STR;
  h['Accept']='text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8';
  h['Accept-Language']='zh-CN,zh;q=0.9,en;q=0.8';
  h['Referer']=getsurl()+'/';
  var c='';
  try{c=String(cache.get('8xCK')||'');}catch(e){}
  if(c)h['Cookie']=c;
  return h;
}
function respText(r){
  if(r==null)return '';
  var b='';
  try{b=String(r.body()||'');}catch(e){}
  if(b)return b;
  return String(r||'');
}
function raw(u){
  var h=hdBase();
  try{return respText(java.get(S(u),S(JSON.stringify(h))));}catch(e1){}
  try{return respText(java.ajax(S(u+','+JSON.stringify({'headers':h}))));}catch(e2){return '';}
}
function ckFromResp(resp){
  var out=[];
  try{
    var hs=resp.headers().values(S('Set-Cookie'));
    for(var i=0;i<hs.size();i++){
      var c=String(hs.get(i));
      c=c.replace(/;\s*Expires=[^;]*/i,'').replace(/;\s*Max-Age=[^;]*/i,'')
         .replace(/;\s*Path=[^;]*/i,'').replace(/;\s*Domain=[^;]*/i,'')
         .replace(/;\s*HttpOnly/i,'').replace(/;\s*Secure/i,'')
         .replace(/;\s*SameSite=[^;]*/i,'');
      out.push(c.trim());
    }
  }catch(e){}
  return out.join('; ');
}
function ckOK(c){return /jieqiUserInfo|jieqiUserId|jieqiUserName/i.test(String(c||''));}
function saveCk(ck){
  if(!ck)return;
  try{source.putLoginHeader(ck);}catch(e){}
  try{cache.put('8xCK',ckMerge(String(cache.get('8xCK')||''),ck));}catch(e){}
}
function whoAmI(){
  var surl=getsurl();
  var h='';
  try{h=raw(surl+'/userdetail.php');}catch(e){}
  if(!h||String(h).length<200)return '';
  if(!/退出登录|logout\.php|我的书架|个人中心/.test(String(h)))return '';
  var m=String(h).match(/jieqiUserName[^>]*>([^<]{1,20})</);
  return m?m[1]:'已登录';
}
function checkLogin(){
  var surl=getsurl();
  var ck='';
  try{ck=String(cookie.getCookie(surl)||'');}catch(e){}
  if(ckOK(ck)){saveCk(ck);java.toast('已登录');java.log('8x 检查登录：cookie 正常 长度='+String(ck).length);return;}
  var who='';
  try{who=whoAmI();}catch(e){}
  if(who){saveCk(ck);java.toast('已登录：'+who);java.log('8x 检查登录：页面判定已登录');}
  else{java.toast('未登录');java.log('8x 检查登录：未登录 cookie长度='+String(ck).length);}
}
function weblogin(){
  var surl=getsurl();
  try{source.removeLoginHeader();}catch(e){}
  var url=surl+'/login.php';
  java.toast('正在打开登录页');
  var opened=false;
  try{try{java.startBrowser(__S(url),__S('八叉登录'),__S(source.bookSourceUrl));opened=true;}catch(e0){}}
  catch(e1){try{java.startBrowser(__S(url));opened=true;}catch(e2){java.toast('打开失败: '+e2);}}
  if(!opened)return;
  var ck='',last='';
  for(var i=0;i<160;i++){
    try{Packages.java.lang.Thread.sleep(500);}catch(e){}
    try{ck=String(cookie.getCookie(surl)||'');}catch(e){}
    if(ck&&ck!=last){
      last=ck;
      // 先把手上的 cookie（含 Cloudflare 的 cf_clearance）存下来，
      // 这样即使还没登录，正文请求也能带上过盾凭据
      try{saveCk(ck);}catch(e){}
    }
    if(ckOK(ck))break;
  }
  if(ckOK(ck)){
    saveCk(ck);
    java.toast('登录成功');
    java.log('8x 网页登录成功 cookie长度='+String(ck).length);
  }else{
    var who='';
    try{who=whoAmI();}catch(e){}
    if(who){
      saveCk(ck);
      java.toast('登录成功：'+who);
      java.log('8x 网页登录（页面判定）成功');
    }else{
      java.toast('没检测到登录态；若网页里已登录，请点「🔍检查登录」');
      java.log('8x 网页登录未取到Cookie');
    }
  }
}
function Login(){
  var surl=getsurl();
  var info={};
  try{info=source.getLoginInfoMap()||{};}catch(e){}
  var un=String(info['账号']||'').trim();
  var pw=String(info['密码']||'').trim();
  if(!un||!pw){java.toast('请先填写账号和密码');return;}
  var lg=surl+'/login.php';
  var htm='';
  try{htm=raw(lg);}catch(e){}
  if(String(htm).length<200){java.toast('登录页获取失败，试试「网页登录」');return;}
  var f={},action='';
  try{
    var doc=org.jsoup.Jsoup.parse(__S(htm));
    var fm=doc.select('form').first();
    if(fm!=null){
      action=String(fm.attr('action')||'');
      var ips=fm.select('input');
      for(var i=0;i<ips.size();i++){
        var ip=ips.get(i);
        var n=String(ip.attr('name')||'').trim();
        if(!n)continue;
        var ty=String(ip.attr('type')||'text').toLowerCase();
        if(ty=='submit'||ty=='button'||ty=='image')continue;
        f[n]=String(ip.attr('value')||'');
      }
    }
  }catch(e){}
  f['username']=un;
  f['password']=pw;
  if(!f['act'])f['act']='login';
  if(!f['usecookie'])f['usecookie']='2592000';
  var body=[];
  for(var k in f)body.push(k+'='+encodeURIComponent(f[k]));
  var postUrl=lg;
  if(action&&action.indexOf('http')==0)postUrl=action;
  else if(action&&action.length>0)postUrl=(action.charAt(0)=='/')?surl+action:surl+'/'+action;
  var resp=null;
  try{
    resp=java.post(__S(postUrl),__S(body.join('&')),__S(JSON.stringify(hdBase())));
  }catch(e){java.toast('登录请求失败: '+e);return;}
  var ck='';
  try{ck=ckFromResp(resp);}catch(e){}
  var cj='';
  try{cj=String(cookie.getCookie(surl)||'');}catch(e){}
  var fin=ckOK(ck)?ck:(ckOK(cj)?cj:ckMerge(ck,cj));
  if(ckOK(fin)){
    saveCk(fin);
    java.toast('登录成功');
    java.log('8x 账号登录成功 cookie长度='+String(fin).length);
  }else{
    var msg='';
    try{msg=String(resp.body()||'');}catch(e){}
    msg=msg.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
    java.toast('登录失败：'+(msg.substring(0,40)||'检查账号密码或验证码'));
    java.log('8x 账号登录失败 '+msg.substring(0,120));
  }
}
function re(){
  var surl=getsurl();
  var ck='';
  try{ck=String(source.getLoginHeader()||'');}catch(e){}
  var o={'headers':hdBase()};
  if(ck)o['headers']['Cookie']=ck;
  try{java.ajax(__S(surl+'/logout.php,'+JSON.stringify(o)));}catch(e){}
  try{cookie.removeCookie(surl);}catch(e){}
  try{cache.delete('8xCK');}catch(e){}
  try{source.removeLoginHeader();}catch(e){}
  java.toast('已登出');
}

